import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.Respawn{Position: mgl32.Vec3{1, 2, 3}, State: packet.RespawnStateReadyToSpawn, EntityRuntimeID: 7}
READY_TO_SPAWN = bytes.fromhex("0000803f00000040000040400107")

# generated by gophertunnel b8bd735:
# &packet.Respawn{State: packet.RespawnStateClientReadyToSpawn, EntityRuntimeID: 300}
CLIENT_READY_WIDE_ID = bytes.fromhex("00000000000000000000000002ac02")

GOLDENS = [
    pytest.param(
        v2225.RespawnPacket(
            pos=v2225.Vec3(x=1.0, y=2.0, z=3.0),
            state=v2225.PlayerRespawnState.READY_TO_SPAWN,
            runtime_id=7,
        ),
        READY_TO_SPAWN,
        id="ready-to-spawn",
    ),
    pytest.param(
        v2225.RespawnPacket(state=v2225.PlayerRespawnState.CLIENT_READY_TO_SPAWN, runtime_id=300),
        CLIENT_READY_WIDE_ID,
        id="state-byte-then-wide-runtime-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_respawn_is_packet_45(version):
    assert version.packets[45] is version.RespawnPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_respawn_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_respawn_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
